executed_modules = {level:{int(m):set(g['gene']) for m,g in z.groupby('module')} for level,z in membership.groupby('level')}
candidate_table = pd.read_csv('network_candidates.tsv',sep='\t')
selected_candidates = {level:set(z['gene']) for level,z in candidate_table.groupby('level')}
for level, module_genes in executed_modules.items():
    universe=selected_candidates[level]  # exactly the 1,500 genes selected before clustering
    for module, geneset in executed_modules[level].items():
        for cell in ['astrocyte','microglia','oligodendrocyte','neuron']:
            S=set(markers.loc[markers['class']==cell,'gene']) & universe
            a=len(geneset&S); b=len(geneset)-a; c=len(S-geneset); d=len(universe-geneset-S)
            _, p=fisher_exact([[a,b],[c,d]],alternative='greater')
            odds=((a+.5)*(d+.5))/((b+.5)*(c+.5))
            rows.append({'level':level,'module':module,'marker_set':cell,'module_size':len(geneset),'universe':len(universe),'overlap':a,'odds_ratio':odds,'p':p})
er=pd.DataFrame(rows); er['fdr_bh']=multipletests(er['p'],method='fdr_bh')[1]
assert np.isfinite(er[['odds_ratio','p','fdr_bh']].to_numpy()).all()
er.to_csv('marker_enrichment.tsv',sep='\t',index=False)

